 "选择迭代步骤": "Choose an iteration step",
 "asset_names <- c(\"资产A\",\"资产B\",\"资产C\")": "asset_names <- c(\"Asset A\",\"Asset B\",\"Asset C\")",
 "BS 理论价格（元）": "BS theoretical price (CNY)",
 "Delta Hedging · RStudio 实践": "Delta Hedging · RStudio practice",
